#' Metrics Calculation Functions
#'
#' Functions for calculating various performance metrics
#' for regression and classification models.

#' Calculate specified metrics
#'
#' @param y_true True values
#' @param y_pred Predicted values
#' @param metrics Character vector of metrics to calculate
#' @return List of metric values
#' @details Binary classification metrics require numeric 0/1 labels. Accuracy
#'   and related scores use a probability threshold strictly greater than 0.5.
#'   AUC is missing for a single observed class. Unsupported outcome/metric
#'   combinations return NA. Nonfinite pairs are omitted. R-squared is missing
#'   when the outcome has zero variance. Adjusted R-squared is not supported.
#' @examples
#' calculate_metrics(c(0, 0, 1, 1), c(0.1, 0.3, 0.7, 0.9),
#'                   c("auc", "accuracy", "brier"))
#' @export
calculate_metrics <- function(y_true, y_pred, metrics) {
  if (!(is.numeric(y_true) || is.logical(y_true)) ||
      !(is.numeric(y_pred) || is.logical(y_pred)) || length(y_true) != length(y_pred)) {
    stop("y_true and y_pred must be numeric vectors of equal length")
  }
  if (any(!metrics %in% supported_metrics())) {
    stop("Unsupported metrics: ", paste(setdiff(metrics, supported_metrics()), collapse = ", "))
  }
  results <- stats::setNames(as.list(rep(NA_real_, length(metrics))), metrics)

  # Remove NA values
  valid_idx <- !is.na(y_true) & !is.na(y_pred) & is.finite(y_true) & is.finite(y_pred)
  y_true <- y_true[valid_idx]
  y_pred <- y_pred[valid_idx]

  if (length(y_true) == 0) {
    warning("No valid observations for metric calculation")
    for (metric in metrics) {
      results[[metric]] <- NA_real_
    }
    return(results)
  }

  # Regression metrics
  if ("mse" %in% metrics) {
    results$mse <- mean((y_true - y_pred)^2, na.rm = TRUE)
  }

  if ("rmse" %in% metrics) {
    results$rmse <- sqrt(mean((y_true - y_pred)^2, na.rm = TRUE))
  }

  if ("mae" %in% metrics) {
    results$mae <- mean(abs(y_true - y_pred), na.rm = TRUE)
  }

  if ("r_squared" %in% metrics) {
    ss_res <- sum((y_true - y_pred)^2, na.rm = TRUE)
    ss_tot <- sum((y_true - mean(y_true))^2, na.rm = TRUE)
    results$r_squared <- if (ss_tot > 0) 1 - ss_res / ss_tot else NA_real_
  }

  if ("brier" %in% metrics && all(y_true %in% c(0, 1))) {
    results$brier <- calculate_brier_score(y_true, y_pred)
  }

  # Classification metrics (assumes binary 0/1)
  if (any(c("auc", "c_stat", "accuracy", "sensitivity", "specificity",
            "precision", "recall", "f1") %in% metrics)) {
    # Check if binary classification
    unique_true <- unique(y_true)
    if (all(unique_true %in% c(0, 1))) {
      # Binary classification

      if (length(unique_true) == 2 && ("auc" %in% metrics || "c_stat" %in% metrics)) {
        auc_value <- calculate_auc(y_true, y_pred)
        if ("auc" %in% metrics) results$auc <- auc_value
        if ("c_stat" %in% metrics) results$c_stat <- auc_value
      }

      # For other metrics, need hard classifications
      threshold <- 0.5
      y_pred_class <- ifelse(y_pred > threshold, 1, 0)

      if ("accuracy" %in% metrics) {
        results$accuracy <- mean(y_true == y_pred_class, na.rm = TRUE)
      }

      if ("sensitivity" %in% metrics) {
        tp <- sum(y_true == 1 & y_pred_class == 1)
        fn <- sum(y_true == 1 & y_pred_class == 0)
        results$sensitivity <- ifelse(tp + fn > 0, tp / (tp + fn), NA_real_)
      }

      if ("specificity" %in% metrics) {
        tn <- sum(y_true == 0 & y_pred_class == 0)
        fp <- sum(y_true == 0 & y_pred_class == 1)
        results$specificity <- ifelse(tn + fp > 0, tn / (tn + fp), NA_real_)
      }

      if ("precision" %in% metrics) {
        tp <- sum(y_true == 1 & y_pred_class == 1)
        fp <- sum(y_true == 0 & y_pred_class == 1)
        results$precision <- ifelse(tp + fp > 0, tp / (tp + fp), NA_real_)
      }

      if ("recall" %in% metrics) {
        # Same as sensitivity
        tp <- sum(y_true == 1 & y_pred_class == 1)
        fn <- sum(y_true == 1 & y_pred_class == 0)
        results$recall <- ifelse(tp + fn > 0, tp / (tp + fn), NA_real_)
      }

      if ("f1" %in% metrics) {
        tp <- sum(y_true == 1 & y_pred_class == 1)
        fp <- sum(y_true == 0 & y_pred_class == 1)
        fn <- sum(y_true == 1 & y_pred_class == 0)
        precision <- ifelse(tp + fp > 0, tp / (tp + fp), 0)
        recall <- ifelse(tp + fn > 0, tp / (tp + fn), 0)
        results$f1 <- if (2 * tp + fp + fn > 0) 2 * tp / (2 * tp + fp + fn) else NA_real_
      }
    }
  }

  return(results)
}

#' Calculate AUC (Area Under ROC Curve)
#'
#' @param y_true True binary labels
#' @param y_pred Predicted probabilities
#' @return Numeric AUC value
#' @noRd
calculate_auc <- function(y_true, y_pred) {
  # Try using pROC if available
  if (requireNamespace("pROC", quietly = TRUE)) {
    tryCatch({
      roc_obj <- pROC::roc(y_true, y_pred, quiet = TRUE, direction = "<")
      return(as.numeric(pROC::auc(roc_obj)))
    }, error = function(e) {
      # Fall back to manual calculation
      return(calculate_auc_manual(y_true, y_pred))
    })
  } else {
    return(calculate_auc_manual(y_true, y_pred))
  }
}

#' Manual AUC calculation (Mann-Whitney U statistic)
#'
#' @param y_true True binary labels
#' @param y_pred Predicted probabilities
#' @return Numeric AUC value
#' @noRd
calculate_auc_manual <- function(y_true, y_pred) {
  # Remove NAs
  valid <- !is.na(y_true) & !is.na(y_pred)
  y_true <- y_true[valid]
  y_pred <- y_pred[valid]

  if (length(unique(y_true)) != 2) {
    return(NA_real_)
  }

  # Ensure binary coding
  y_true <- as.numeric(y_true)
  if (!all(y_true %in% c(0, 1))) {
    y_true <- ifelse(y_true == min(y_true), 0, 1)
  }

  # Separate predictions by class
  pos_preds <- y_pred[y_true == 1]
  neg_preds <- y_pred[y_true == 0]

  if (length(pos_preds) == 0 || length(neg_preds) == 0) {
    return(NA_real_)
  }

  # Calculate Mann-Whitney U statistic
  n_pos <- length(pos_preds)
  n_neg <- length(neg_preds)

  # Count pairs where positive prediction > negative prediction
  u <- sum(rank(y_pred, ties.method = "average")[y_true == 1]) - n_pos * (n_pos + 1) / 2

  auc <- u / (n_pos * n_neg)
  return(auc)
}

#' Calculate confusion matrix
#'
#' @param y_true True binary labels
#' @param y_pred Predicted probabilities or classes
#' @param threshold Threshold for classification (default 0.5)
#' @return List with confusion matrix components
#' @noRd
calculate_confusion_matrix <- function(y_true, y_pred, threshold = 0.5) {
  y_pred_class <- ifelse(y_pred > threshold, 1, 0)

  tp <- sum(y_true == 1 & y_pred_class == 1)
  tn <- sum(y_true == 0 & y_pred_class == 0)
  fp <- sum(y_true == 0 & y_pred_class == 1)
  fn <- sum(y_true == 1 & y_pred_class == 0)

  return(list(
    tp = tp,
    tn = tn,
    fp = fp,
    fn = fn,
    accuracy = (tp + tn) / (tp + tn + fp + fn),
    sensitivity = tp / (tp + fn),
    specificity = tn / (tn + fp),
    precision = tp / (tp + fp),
    npv = tn / (tn + fn),
    f1 = 2 * tp / (2 * tp + fp + fn)
  ))
}

#' Calculate Brier score
#'
#' @param y_true True binary labels
#' @param y_pred Predicted probabilities
#' @return Numeric Brier score
#' @noRd
calculate_brier_score <- function(y_true, y_pred) {
  mean((y_true - y_pred)^2, na.rm = TRUE)
}

#' Calculate calibration metrics
#'
#' @param y_true True binary labels
#' @param y_pred Predicted probabilities
#' @param n_bins Number of bins for calibration
#' @return List with calibration statistics
#' @noRd
calculate_calibration <- function(y_true, y_pred, n_bins = 10) {
  # Create bins
  breaks <- seq(0, 1, length.out = n_bins + 1)
  bins <- cut(y_pred, breaks = breaks, include.lowest = TRUE)

  # Calculate observed proportion in each bin
  calibration_df <- data.frame(
    predicted = y_pred,
    observed = y_true,
    bin = bins
  )

  calibration_summary <- aggregate(observed ~ bin, data = calibration_df,
                                  FUN = function(x) c(mean = mean(x), n = length(x)))

  return(calibration_summary)
}
